// app.js – Security‑hardened starter

// -------------------------------------------------------------------
// Load environment (development only) --------------------------------
if (process.env.NODE_ENV !== 'production') {
  // dotenv is a dev‑dependency; it won't be shipped in production builds.
  require('dotenv').config({ path: '.env.test' });
}

// -------------------------------------------------------------------
// Core dependencies -------------------------------------------------
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan'); // request logging

// -------------------------------------------------------------------
// App initialization ------------------------------------------------
const app = express();

// -------------------------------------------------------------------
// Security middlewares ------------------------------------------------
app.disable('x-powered-by');                 // hide framework fingerprint
app.use(helmet());                           // secure HTTP headers
app.use(
  cors({
    origin: ['https://my-frontend.example.com'], // whitelist your front‑ends
    methods: ['GET', 'POST', 'OPTIONS'],
  })
);

// Rate limiting: 100 requests per 15‑minute window per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Logging (only in dev; can be tuned for prod)
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// -------------------------------------------------------------------
// Routes -------------------------------------------------------------
app.get('/health', (req, res) => {
  // No sensitive data returned
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would come from a DB with proper RBAC
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// -------------------------------------------------------------------
//  Generic error handler (hide stack traces in prod) -----------------
app.use((err, _req, res, _next) => {
  console.error(err); // still log internally
  const status = err.status || 500;
  const response = {
    error: err.message || 'Internal Server Error',
  };
  // In production do not expose stack traces
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// -------------------------------------------------------------------
// Server start -------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;
```

