## 3️⃣ Sample Refactored `app.js`

Below is a **minimal yet secure** rewrite that incorporates the above recommendations while preserving the original functionality.

```js
'use strict';

// ──────────────────────────────────────────────────────────────
//  Dependencies
// ──────────────────────────────────────────────────────────────
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan'); // structured logging (optional)

// ──────────────────────────────────────────────────────────────
//  App setup
// ──────────────────────────────────────────────────────────────
const app = express();

// Security headers
app.use(helmet());

// CORS whitelist (adjust as needed)
const allowedOrigins = ['https://mytrusteddomain.com'];
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser requests (e.g., curl, Postman) when origin is undefined
      if (!origin || allowedOrigins.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
  })
);

// Rate limiting – 100 req / 15 min per IP
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Logging (in production you may switch to pino/winston)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ──────────────────────────────────────────────────────────────
//  Routes
// ──────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app this would be behind auth & source from DB
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ──────────────────────────────────────────────────────────────
//  Error handling (must be after all route definitions)
// ──────────────────────────────────────────────────────────────
app.use((err, _req, res, _next) => {
  // Log the error (avoid leaking details to client)
  console.error(err);
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// ──────────────────────────────────────────────────────────────
//  Server start
// ──────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`Server listening on port ${PORT}`);
});

module.exports = Object.freeze(app);
```

**What changed?**

* Added **Helmet**, **CORS**, **rate‑limit**, and **Morgan** for security and observability.  
* Used environment variable for the port.  
* Implemented a generic error‑handler that never leaks stack traces.  
* Exported a frozen `app` object to avoid accidental mutation.  
* Added `'use strict'` directive.  

