  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // max 100 requests per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(apiLimiter);

// Uncomment and configure CORS if this API will be consumed from browsers.
// app.use(cors({ origin: 'https://my.trusted.domain' }));

// ------------------------------------------------------------------
// Routes
// ------------------------------------------------------------------
app.get('/health', (req, res) => {
  // If you need the timestamp for monitoring, keep it; otherwise omit.
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real world app you would protect this route with authentication.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ------------------------------------------------------------------
// Centralized error handling (must be after all routes)
// ------------------------------------------------------------------
app.use((err, _req, res, _next) => {
  console.error(err); // internal logging
  res.status(500).json({ error: 'Internal Server Error' });
});

// ------------------------------------------------------------------
// Server start – respect PORT env var for deploy flexibility
// ------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown (useful for containers / serverless platforms)
function shutdown() {
  console.log('Shutting down server...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

**Key additions:**

* Helmet headers and removal of `X-Powered-By`.
* Rate limiting applied globally.
* Central error handler to avoid leaking stack traces.
