```js
// app.js
// Secure Express server – demonstrates best‑practice mitigations

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ==== Middleware ====
// Secure HTTP headers
app.use(helmet());

// CORS – restrict to trusted origins (adjust as needed)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    methods: ['GET'],
  })
);

// Rate limiting – 100 requests per 15 minutes per IP
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// ==== Routes ====

// Health check – minimal information
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example users endpoint.
 * In a real app, this would be protected and would not expose raw email addresses.
 */
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice' }, // email omitted for privacy
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// ==== Error handling ====
// Catch‑all async errors
app.use((err, _req, res, _next) => {
  console.error(err); // consider structured logging in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// ==== Server start ====
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`✅ Server listening on port ${PORT}`);
});

module.exports = app;
```

