```js
const express = require('express');
const helmet = require('helmet');               // sets secure HTTP headers
const cors = require('cors');                   // configure if you need cross‑origin access
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');               // request logging (avoid logging bodies)
const dotenv = require('dotenv');

dotenv.config();   // load .env variables (optional but recommended)

// Create the Express app
const app = express();

// ---- Security hardening ----------------------------------------------------
app.disable('x-powered-by');        // hide Express version
app.use(helmet());                  // set CSP, HSTS, X‑Content‑Type‑Options, etc.
app.use(cors({                     // tighten CORS if you know allowed origins
  origin: process.env.CORS_ORIGIN || '*', // replace '*' with a whitelist in prod
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,   // 15 minutes
    max: 100,                   // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
  })
);
app.use(morgan('combined'));   // HTTP request logging (no bodies)
```

### 3.2 Add a global error handler (no stack traces in production)

```js
// Central error handling – place after all route definitions
app.use((err, req, res, next) => {
  // Log the error (you could plug in Winston, Pino, etc.)
  console.error(err);

  // Do NOT expose stack traces to the client in production
  const response = {
    message: process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message,
  };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});
```

